 head=subprocess.check_output(['git','-C',str(REPO),'rev-parse','HEAD'],text=True).strip();env={**os.environ,'CUDA_VISIBLE_DEVICES':'','PYTHONPATH':str(REPO/'src')};validation=json.loads(subprocess.check_output([str(REPO.parent/'.conda/envs/vitnns/bin/python'),'scripts/validate_nns_vit_patch_depth_s4_r12.py','validate'],cwd=REPO,text=True,env=env));falsepass=json.loads(subprocess.check_output([str(REPO.parent/'.conda/envs/vitnns/bin/python'),'scripts/validate_nns_vit_patch_depth_s4_r12.py','false-pass'],cwd=REPO,text=True,env=env));r12.require(validation['status']=='PASS_POST_HOC_EXPLORATORY' and falsepass['status']=='PASS','R12 validation did not pass')
